SELECT
  {% if agg_cols -%}
  {{ agg_cols | join_list_with_prefix('a') }},
  {%- endif %}
  AVG(conversion_val) AS conversion_val
FROM `{{ project_id }}.{{ dataset_id }}.mondaysmart_currency_conversion` c

{% if "".join(agg_cols).strip().__len__() > 0 -%}
CROSS JOIN (
    SELECT {{ agg_cols | join_list_with_prefix('') }}
    FROM `{{ project_id }}.{{ dataset_id }}.mondaysmart_sales_subset_daily`
    WHERE {{ timeline_where_clause }}
      {% if where_clause %} AND {{ where_clause }} {% endif %}
      AND {{ agg_cols[0] }} IS NOT NULL

    UNION DISTINCT

    SELECT {{ agg_cols | join_list_with_prefix('') }}
    FROM `{{ project_id }}.{{ dataset_id }}.mondaysmart_inventory_subset_daily`
    WHERE {{ timeline_where_clause }}
      {% if where_clause %} AND {{ where_clause }} {% endif %}
      AND {{ agg_cols[0] }} IS NOT NULL

    UNION DISTINCT

    SELECT {{ agg_cols | join_list_with_prefix('') }}
    FROM `{{ project_id }}.{{ dataset_id }}.mondaysmart_planned_subset_daily`
    WHERE {{ timeline_where_clause }}
      {% if where_clause %} AND {{ where_clause }} {% endif %}
      AND {{ agg_cols[0] }} IS NOT NULL
) AS a 
{%- endif %}

WHERE {{ timeline_where_clause.replace("week_id", "c.week_id").replace("date_id", "c.date_id") }}
{% if currency_code %}
  AND currency_code = '{{ currency_code }}'
{% endif %} 

{% if agg_cols -%}
GROUP BY {{ agg_cols | join_list_with_prefix('a') }}
{%- endif %}
